  '6': { w: 3.8, s: [[3.3, 0.7, 2.4, 0.1, 1.2, 0.5, 0.2, 2.7, 0.2, 5, 1, 6.8, 2.6, 6.8, 3.6, 5.4, 3.2, 3.9, 1.7, 3.6, 0.2, 4.3]] },
