  '8': { w: 3.8, s: [[1.9, 0, 3, 0.4, 3.4, 1.5, 2.7, 3, 1.1, 3, 0.4, 1.5, 0.8, 0.4, 1.9, 0], [1.1, 3.1, 3.1, 3.5, 3.7, 5.1, 2.7, 6.8, 1.1, 6.8, 0.1, 5.1, 0.7, 3.5, 1.1, 3.1]] },
